"use strict";
// A CommonJS package that runs in a Node island. The program holds its
// functions through several types and compares them.
function compare(a, b) {
  return a < b ? -1 : a > b ? 1 : 0;
}
function double(n) {
  return n * 2;
}
function isEven(n) {
  return n % 2 === 0;
}
// What the island sees when the program hands a function back.
function isDouble(f) {
  return f === double;
}
function applyTo(f, x) {
  return f(x);
}
function pickDouble() {
  return double;
}
const registry = { double, compare };
module.exports = { compare, double, isEven, isDouble, applyTo, pickDouble, registry };
